\label{th1l} 
Let\/  $0< r_0< r<+\infty$, $1<k\in {\mathbb{R}}^+$,  $E\subset [0,r]$ be ${\rm mes}$-me\-a\-s\-u\-r\-a\-b\-le, 
$g\in L^p(E)$, where $1<p\leq \infty$ and $q\in [1,+\infty)$ is defined by $\dfrac{1}{p}+\dfrac{1}{q}=1$.
If $U\not\equiv \pm\infty$  is a non-trivial $\delta$-subharmonic   functions on ${\mathbb{C}}$, 
and $u\not\equiv -\infty$ is a subharmonic function on ${\mathbb{C}}$,  then 
\begin{subequations}\label{1l}
\begin{flalign}
\int_{E} {\sf M}_{U^+}(t)g(t){\,{\rm d}} t&\leq
\frac{4qk}{k-1} \bigl({\sf T}_{U}(r_0,kr)+{\sf C}_{U^+}(r_0)\bigr)\|g\|_{L^p(E)} \sqrt[q]{{\rm mes} \,E}
\ln\frac{4kr}{{\rm mes} \,E},
\tag{\ref{1l}T}\label{inDl+l}
\\ 
\int_{E} {\sf M}_{|u|}(t)g(t){\,{\rm d}} t& \leq
\frac{5qk}{k-1} \bigl({\sf M}_{u^+}(kr)+{\sf C}_{u^-}(r_0)\bigr) \sqrt[q]{{\rm mes} \,E}
\ln\frac{4kr}{{\rm mes} \,E}.
\tag{\ref{1l}M}\label{uMl}
\end{flalign}
\end{subequations}

Let, under the conditions of Theorem\/ {\rm \ref{th1l}}, $F\not\equiv 0$ be a meromorphic function, and $f\not\equiv 0$ be an entire function.
Then, in the traditional notation  \eqref{{TN}M}--\eqref{{TN}N}, we have
\begin{subequations}\label{1lf}
\begin{flalign}
\int_{E} \bigl(\ln^+ M(t,F)\bigr)g(t){\,{\rm d}} t&\leq
\frac{4qk}{k-1} \bigl( T(kr,F)-N(r_0,F)\bigr)\|g\|_{L^p(E)} \sqrt[q]{{\rm mes}\,E}
\ln\frac{4kr}{{\rm mes} \,E},
\tag{\ref{1l}T}\label{inDl+lf}
\\ 
\int_{E} \bigl|\ln M(t,f)\bigr|                          
g(t){\,{\rm d}} t& \leq
\frac{5qk}{k-1} \bigl(\ln^+ M(kr,f)+m(r_0,1/f )                    
\bigr) \sqrt[q]{{\rm mes} \,E}
\ln\frac{4kr}{{\rm mes} \,E}.
\tag{\ref{1l}M}\label{uMlf}
\end{flalign}
\end{subequations}

Our elementary example \cite[1.1, (3)]{KhaMst} shows that it is impossible to discard the terms $-N(r_0,F)$ and 
$m(r_0,1/f )$ in parentheses on the right-hand sides of inequality \eqref{inDl+lf} and \eqref{uMlf}, respectively.
In particular, the classical Rolf Nevanlinna Theorem \cite[Ch.~1, Theorem 7.2]{GOe}  can be formulated in the following correct form: {\it for each meromorphic function   $F\not\equiv 0$ and   $1<k\in {\mathbb{R}}^+$}
\begin{equation}
\frac{1}{r}\int_0^r \ln^+ M(t,F){\,{\rm d}} t\leq
\frac{4k\ln 4k}{k-1} \bigl( T(kr,F)-N(r_0,F)\bigr)\quad \text{\it for all\/ $0<r_0\leq r\in {\mathbb{R}}^+$.}
 \end{equation}
Indeed, it is sufficient to choose $E:=[0,r]$, $g\equiv 1$ with ${\rm mes} \,E=r$, and $p:=\infty$ with $q=1$ in \eqref{inDl+lf}.

\label{th1} 
Let  $0< r_0< r<+\infty$, $1<k\in {\mathbb{R}}^+$,  $E\subset \overline D(r)$ be a $\uplambda$-measurable subset. If  
$U\not\equiv \pm\infty$  is a $\delta$-subharmonic  functions on ${\mathbb{C}}$, 
and $u\not\equiv -\infty$ is a subharmonic function on ${\mathbb{C}}$,  then 
\begin{subequations}\label{1}
\begin{flalign}
\int_{E} U^+{\,{\rm d}} \uplambda \leq
\frac{2k}{k-1} \bigl({\sf T}_{U}(r_0,kr)+{\sf C}_{U^+}(r_0)\bigr)\uplambda(E)
\ln\frac{100kr^2}{\uplambda (E)},
\tag{\ref{1}T}\label{inDl+}
\\ 
\int_{E} |u|{\,{\rm d}} \uplambda \leq
\frac{3k}{k-1} \bigl({\sf M}_{u^+}(kr)+{\sf C}_{u^-}(r_0)\bigr) \uplambda(E) \ln\frac{100kr^2}{\uplambda (E)}.
\tag{\ref{1}M}\label{uM}
\end{flalign}
\end{subequations}

If $U\not\equiv \pm\infty$  be a $\delta$-subharmonic  functions on ${\mathbb{C}}$, and 
$u\not\equiv -\infty$ be a subharmonic function on ${\mathbb{C}}$,  then
\begin{subequations}\label{10}
\begin{flalign}
{\sf B}_{U^+}(r) &\leq
\frac{7k\ln (ek)}{k-1} \bigl({\sf T}_{U}(r_0,kr)+{\sf C}_{U^+}(r_0)\bigr) 
\quad\text{for all\/ $0<r_0<r\in \mathbb R^+$  and $1<k\in {\mathbb{R}}^+$},
\tag{\ref{10}T}\label{inDl+0}
\\ 
{\sf B}_{|u|}(r) &\leq
\frac{11k\ln (ek)}{k-1} \bigl({\sf M}_{u^+}(kr)+{\sf C}_{u^-}(r_0)\bigr) \quad\text{for all\/ $0<r_0<r\in \mathbb R^+$  and $1<k\in {\mathbb{R}}^+$}.
\tag{\ref{10}M}\label{uM0}
\end{flalign}
\end{subequations}

Let, under the conditions of Theorem\/ {\rm \ref{th1}}, $F\not\equiv 0$ be a meromorphic function, and $f\not\equiv 0$ be an entire function.
Then, in the traditional notation  \eqref{{TN}M}--\eqref{{TN}N} and \eqref{BF}, we have
\begin{subequations}\label{1lfF}
\begin{flalign}
\int_{E} \ln^+ \bigl|F(z)\bigr|{\,{\rm d}} \uplambda(z)&\leq
\frac{2k}{k-1} \bigl( T(kr,F)-N(r_0,F)\bigr) \uplambda(E)
\ln\frac{100kr^2}{\uplambda (E)},
\tag{\ref{1lfF}T}\label{inDl+lfF}
\\ 
\int_{E} \Bigl|\ln \bigl|f(z)\bigr|\Bigr| {\,{\rm d}} \uplambda(z)& \leq
\frac{3k}{k-1} \bigl(\ln^+ M(kr,f)+m(r_0,1/f )                    
\bigr) \ln\frac{100kr^2}{\uplambda (E)}.
\tag{\ref{1lfF}M}\label{uMlfF}
\\
{m^{[2]}}(r,F)&\leq
\frac{7k\ln (ek)}{k-1}\bigl( T(kr,F)-N(r_0,F)\bigr),
\tag{\ref{1lfF}F}\label{inDl+0l}
\\ 
{m^{[2]}}(r,f)+{m^{[2]}}(r,1/f) &\leq
\frac{11k\ln (ek)}{k-1} \bigl({\sf M}_{u^+}(kr)+{\sf C}_{u^-}(r_0)\bigr) 
                                                                              
\tag{\ref{1lfF}f}\label{uM0l}
\end{flalign}
\end{subequations}
for all\/ $0<r_0<r\in \mathbb R^+$  and $1<k\in {\mathbb{R}}^+$.

\label{lem1} Let\/  $0\leq r<R<+\infty$,  $E\subset \overline D(r)$ be $\uplambda$-measurable, $U=u-v$  be a difference of subharmonic  functions $u, v\in {\sf sbh}_* \bigl(\overline D(R)\bigr)$,    
$\varDelta_v$ be the Riesz measure of $v$. Then 
\begin{equation}\label{inDR}
\int_{E} U^+{\,{\rm d}} \uplambda\leq \frac{1}{2}\Bigl(\frac{R+r}{R-r}
{\sf C}_{U^+}(R)+\varDelta_v^{{\text{\tiny\rm rad}}}(R)\Bigr) \uplambda(E)\ln\frac{(10R)^2}{\uplambda(E)}.
\end{equation}

For $w\in E\subset \overline D(r)$, by the Poisson\,--\,Jensen formula \cite[4.5]{Rans}, we have
\begin{multline*}
U(w)=\frac{1}{2\pi}\int_0^{2\pi}U(Re^{i\varphi}){\rm Re} \frac{Re^{i\varphi}+w}{Re^{i\varphi}-w}{\,{\rm d}} \varphi
-\int_{D(R)}\ln \Bigl|\frac{R^2-z\bar w}{R(w-z)}\Bigr|{\,{\rm d}} \varDelta_u(z) \\
+\int_{D(R)}\ln \Bigl|\frac{R^2-z\bar w}{R(w-z)}\Bigr|{\,{\rm d}} \varDelta_v(z)  
\leq \frac{R+r}{R-r}{\sf C}_{U^+}(R) +\int_{D(R)}\ln \frac{2R}{|w-z|}{\,{\rm d}} \varDelta_v(z) 
\end{multline*}
where the right-hand side of the inequality is positive. Hence, by integrating, we get 
\begin{multline}\label{intU}
\int_{E} U^+{\,{\rm d}} \uplambda \leq \frac{R+r}{R-r}{\sf C}_{U^+}(R)\uplambda(E)+
\int_{D(R)}\int_E\ln\frac{2R}{|w-z|}{\,{\rm d}} \uplambda (w){\,{\rm d}} \varDelta_v(z)\\
\leq \frac{R+r}{R-r}{\sf C}_{U^+}(R)\uplambda(E)+
\varDelta_v\bigl(\overline D(R)\bigr)
\int_E\ln\frac{2R}{|w-z|}{\,{\rm d}} \uplambda (w). 
\end{multline}
Denote by  $\uplambda_E$ the restriction of the Lebesgue measure  $\uplambda$ to $\uplambda$-measurable set $E\subset \overline D(r)$. 
Obviously, 
\begin{subequations}\label{lE1}
\begin{align}
{\rm supp\,} \uplambda_E&\subset \overline D(r)\subset D(R),
\tag{\ref{lE1}s}\label{{lE}s}\\
\uplambda_E(w,t)&\overset{\eqref{{murad}z}}{\leq} \pi t^2\quad\text{for each $w\in {\mathbb{C}}$ and $t\in {\mathbb{R}}^+$}, 
\tag{\ref{lE1}t}\label{{lE}t}\\
  \uplambda_E ({\mathbb{C}})&=\uplambda (E)\leq \pi r^2\leq \pi R^2.
\tag{\ref{lE1}E}\label{{lE}E}
\end{align}
\end{subequations} 
Consider the last integral in \eqref{intU}:
\begin{equation}\label{lI}
\int_E\ln\frac{2R}{|w-z|}{\,{\rm d}} \uplambda (w) =\int_{{\mathbb{C}}} \ln\frac{2R}{|w-z|}{\,{\rm d}} \uplambda_E (w)
\overset{\eqref{{lE}s}}{=}\int_0^{2R} \ln \frac{2R}{t}{\,{\rm d}} \uplambda_E (z;t)
\overset{\eqref{{lE}t}}{=}
\int_0^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t.
\end{equation}
 By \eqref{{lE}E} we  have $\sqrt{\uplambda (E)}\overset{\eqref{{lE}E}}{\leq} \sqrt{\pi}r< 2r \leq 2R$.
From here we can split the last integral in \eqref{lI} into the sum of two positive integrals:
\begin{equation}\label{=E}
\int_0^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t=
\int_0^{\sqrt{\uplambda (E)}} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t+\int_{\sqrt{\uplambda (E)}}^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t
\end{equation}
Using \eqref{{lE}t}, we have for first integral on the right-hand  side of this equality \eqref{=E} the estimate
\begin{equation}\label{=E1}
\int_0^{\sqrt{\uplambda (E)}} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t\overset{\eqref{{lE}t}}{\leq} 
\int_0^{\sqrt{\uplambda (E)}} \frac{\pi t^2}{t}{\,{\rm d}} t=\frac{\pi}{2}\uplambda (E). 
\end{equation}
Using \eqref{{lE}E}, we have for second integral on the right-hand  side of  \eqref{=E} the estimate
\begin{equation}\label{=E2}
\int_{\sqrt{\uplambda (E)}}^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t\leq 
\uplambda({\mathbb{C}})\int_{\sqrt{\uplambda (E)}}^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t
\overset{\eqref{{lE}E}}{=} 
\frac12\uplambda(E) \ln \frac{4R^2}{\uplambda (E)}. 
\end{equation}
Thus, it follows from \eqref{=E1}--\eqref{=E2} and \eqref{=E} that
\begin{equation}\label{=E0}
\int_0^{2R} \frac{\uplambda_E (z;t)}{t}{\,{\rm d}} t\leq 
\frac{\pi}{2}\uplambda (E)+\frac12\uplambda(E) \ln \frac{4R^2}{\uplambda (E)} =
\frac{1}{2}\uplambda (E)\ln \frac{4e^{\pi}R^2}{\uplambda(E)}\leq 
\frac{1}{2}\uplambda (E)\ln \frac{(10R)^2}{\uplambda(E)},
\end{equation}
where
\begin{equation*}
\ln \frac{(10R)^2}{\uplambda(E)}\geq 2, \text{ since } \uplambda(E)\overset{\eqref{{lE}E}}{\leq} \pi R^2,
\end{equation*}
and estimate \eqref{=E0} together with \eqref{lI} and \eqref{intU} gives \eqref{inDR}.

\label{lem2} Let $\mu\in {\sf Meas\,}^+\bigl(\overline D(R)\bigr)$. Then
\begin{equation}\label{N}
\mu^{{\text{\tiny\rm rad}}}(r)\leq  \frac{R}{R-r}{\sf N}_{\mu}(r,R)\quad \text{for each $0\leq r\leq R$.}
\end{equation}

\label{lem3} Let  $0< r<+\infty$, $0<b\in {\mathbb{R}}^+$,  $E\subset \overline D(r)$ be $\uplambda$-measurable, $U=u-v$  be a difference of subharmonic  functions $u, v\in {\sf sbh}_* \Bigl(\overline D\bigl((1+b)^2r\bigr)\Bigr)$. Then 
\begin{equation}\label{inDl}
\int_{E} U^+{\,{\rm d}} \uplambda \leq
                         
\frac{2+b}{2b}
\Bigl(
{\sf C}_{U^+}\bigl((1+b)r\bigr)
+{\sf N}_{\varDelta_v}\bigl((1+b)r, (1+b)^2r\bigr)\Bigr)
\uplambda(E)\ln\frac{\bigl(10(1+b)r\bigr)^2}{\uplambda(E)}. 
\end{equation}

By Lemma \ref{lem1} 
with  $R:=(1+b)r$ we have 
\begin{equation*}
\int_{E} U^+{\,{\rm d}} \uplambda \leq \frac{1}{2}\Bigl(\frac{2+b}{b}
{\sf C}_{U^+}(R)+\varDelta_v^{{\text{\tiny\rm rad}}}\bigl((1+b)r\bigr)\Bigr) \uplambda(E)\ln\frac{\bigl(10(1+b)r\bigr)^2}{\uplambda(E)}.
\end{equation*}
Hence, by Lemma \ref{lem2} with $(1+b)^2r$ instead of $R$ and $(1+b)r$ instead of $r$, we obtain
\begin{equation*}
\int_{E} U^+{\,{\rm d}} \uplambda \leq \frac{1}{2}\frac{2+b}{b}
\Bigl({\sf C}_{U^+}\bigl((1+b)r\bigr)
+{\sf N}_{\varDelta_v}\bigl((1+b)r,(1+b)^2r\bigr) \Bigr) 
\uplambda(E)\ln\frac{\bigl(10(1+b)r\bigr)^2}{\uplambda(E)},
\end{equation*}
 which gives \eqref{inDl}.

We can assume that $U=u-v$ is the canonical representation of $U$. 
Consider a number $b>0$ such that $(1+b)^2=k$. By Lemma \ref{lem3}, we have
\begin{multline*}
\int_{E}U^+{\,{\rm d}} \uplambda \leq
\frac12\frac{\sqrt{k}+1}{\sqrt{k}-1}
\Bigl( {\sf C}_{U^+}(\sqrt{k}r)
+{\sf N}_{\varDelta_v}(\sqrt{k}r, kr)\Bigr)
\uplambda(E)\ln\frac{\bigl(10\sqrt{k}r\bigr)^2}{\uplambda(E)}
\\ 
\leq \frac{k}{k-1}
\Bigl( \underset{{\sf T}_{U}(r_0, \sqrt{k}r)}{\underbrace{{\sf C}_{U^+}(r_0, \sqrt{k}r)+{\sf N}_{\varDelta_v}(r_0, \sqrt{k}r)}}+{\sf C}_{U^+}(r_0)
+\underset{{\sf T}_{U}(r_0, kr)}{\underbrace{{\sf C}_{U^+}(r_0, kr)+{\sf N}_{\varDelta_v}(r_0, kr)}}\Bigr)\uplambda(E)\ln\frac{\bigl(10r\bigr)^2k}{\uplambda(E)}\\
\leq 
\frac{k}{k-1}
\Bigl( 2{\sf T}_{U}(r_0, kr)+{\sf C}_{U^+}(r_0)\Bigr)\uplambda(E)\ln\frac{\bigl(10r\bigr)^2k}{\uplambda(E)}
\leq \frac{2k}{k-1}
\Bigl( {\sf T}_{U}(r_0, kr)+{\sf C}_{U^+}(r_0)\Bigr)\uplambda(E)\ln\frac{\bigl(100kr^2}{\uplambda(E)}
\end{multline*}
and obtain  \eqref{inDl+}. 

If $u\in {\sf sbh}_*({\mathbb{C}})$, then the function  ${\sf M}_u^+$ is increasing, and
\begin{equation}\label{M+E}
\int_{E} u^+{\,{\rm d}} \uplambda \overset{\eqref{{Cu}M}}{\leq}
{\sf M}_{u^+}(r) \uplambda (E) \quad \text{for $E\subset \overline D(r)$.}
\end{equation}
For  $U_u:=0-u$, the difference  $0-u$ is the canonical representation of $\delta$-subharmonic non-trivial function $U_u$ and  we have
\begin{equation}\label{TCM}
{\sf T}_{U_u}(r,R)\overset{\eqref{T}}{=}  {\sf C}_{\sup\{0,u\}}(r,R)={\sf C}_{u^+}(r,R)\leq  {\sf C}_{u^+}(R)
\leq {\sf M}_{u^+}(R).
\end{equation}
Hence, by Theorem \ref{th1} in part \eqref{inDl+} for $U_u$ in the role of $U$, we obtain  
   
\begin{multline*}
\int_{E} (-u)^+{\,{\rm d}} \uplambda \overset{\eqref{inDl+}}{\leq}
\frac{2k}{k-1} \Bigl({\sf T}_{U_u}(r_0,kr)+{\sf C}_{U_u^+}(r_0)\Bigr)
\uplambda(E) \ln\frac{100kr^2}{\uplambda (E)}
\\
\overset{\eqref{TCM}}{\leq}
\frac{2k}{k-1} \Bigl({\sf M}_{u^+}(kr)+{\sf C}_{(-u)^+}(r_0)\Bigr)\uplambda(E) \ln\frac{100kr^2}{\uplambda (E)}. 
\end{multline*}
The latter together with \eqref{M+E} gives \eqref{uM}.
